import java.util.Scanner;

class Policy {
    protected String name;
    protected double sum;

    public Policy(String name, double sum) {
        this.name = name;
        this.sum = sum;
    }

    public void display() {
        System.out.println("Policy Holder: " + name + "\nSum Assured: " + sum);
    }
}

class LifeInsurance extends Policy {
    private int term;

    public LifeInsurance(String name, double sum, int term) {
        super(name, sum);
        this.term = term;
    }

    public void calc() {
        display();
        System.out.printf("Premium: %.1f\n", (sum * 3 * term) / 1000.0);
    }
}

class HealthInsurance extends Policy {
    private int age;

    public HealthInsurance(String name, double sum, int age) {
        super(name, sum);
        this.age = age;
    }

    public void calc() {
        display();
        double p = age < 45 ? (sum * 2) / 100.0 : (sum * 4) / 100.0;
        System.out.printf("Premium: %.1f\n", p);
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        try {
            String type = s.nextLine().trim();
            String name = s.nextLine().trim();
            double sum = s.nextDouble();
            int val = s.nextInt();

            if (name.isEmpty() || name.matches(".*\\d.*") || sum <= 0) {
                System.out.println("Invalid Input");
                return;
            }

            if (type.equals("Life") && val >= 5 && val <= 30) {
                new LifeInsurance(name, sum, val).calc();
            } else if (type.equals("Health") && val >= 18 && val <= 100) {
                new HealthInsurance(name, sum, val).calc();
            } else {
                System.out.println("Invalid Input");
            }
        } catch (Exception e) {
            System.out.println("Invalid Input");
        }
    }
}

import java.util.Scanner;

class Policy {
    protected String name;
    protected double sumAssured;
    Policy(String name, double sumAssured) { this.name = name; this.sumAssured = sumAssured; }
}

class LifeInsurance extends Policy {
    private int term;
    LifeInsurance(String name, double sumAssured, int term) { super(name, sumAssured); this.term = term; }
    void display() { System.out.printf("Policy Holder: %s\nSum Assured: %.1f\nPremium: %.1f\n", name, sumAssured, (sumAssured * 3 * term) / 1000.0); }
}

class HealthInsurance extends Policy {
    private int age;
    HealthInsurance(String name, double sumAssured, int age) { super(name, sumAssured); this.age = age; }
    void display() { System.out.printf("Policy Holder: %s\nSum Assured: %.1f\nPremium: %.1f\n", name, sumAssured, sumAssured * (age < 45 ? 2 : 4) / 100.0); }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        try {
            String type = sc.nextLine().trim(), name = sc.nextLine().trim();
            double sum = Double.parseDouble(sc.nextLine().trim());
            int val = Integer.parseInt(sc.nextLine().trim());

            if (name.matches(".*\\d.*") || name.isEmpty() || sum <= 0) throw new Exception();

            if (type.equals("Life") && val >= 5 && val <= 30) {
                new LifeInsurance(name, sum, val).display();
            } else if (type.equals("Health") && val >= 18 && val <= 100) {
                new HealthInsurance(name, sum, val).display();
            } else throw new Exception();
        } catch (Exception e) {
            System.out.println("Invalid Input");
        } finally { sc.close(); }
    }
}

